import datasets
import re
import numpy as np

ds = datasets.load_from_disk('/app/data')

def extract_params(name):
    """Extract parameter count in millions. Return None if unknown."""
    # Clean the name
    name_lower = name.lower()
    # Patterns
    match = re.search(r'(\d+\.?\d*)\s*([mb])', name_lower)
    if match:
        num = float(match.group(1))
        unit = match.group(2)
        if unit == 'b':
            return num * 1000  # billions to millions
        elif unit == 'm':
            return num
    # Special cases
    if 'amber' in name_lower:
        return 7000.0  # Amber is ~7B
    return None

# Build dictionary of model -> params
model_params = {}
for i in range(len(ds)):
    m = ds[i]['model_name']
    if m not in model_params:
        p = extract_params(m)
        if p is not None:
            model_params[m] = p
        else:
            model_params[m] = None

# Print model -> params mapping
print("Model parameters (in millions):")
for m, p in sorted(model_params.items(), key=lambda x: x[1] if x[1] is not None else -1):
    print(f"  {m:50s} -> {p}")

# Check if flops is consistent per model across groups
from collections import defaultdict
model_flops = defaultdict(list)
for i in range(len(ds)):
    m = ds[i]['model_name']
    model_flops[m].append(ds[i]['flops'])

print("\nFlops consistency per model:")
for m, flist in sorted(model_flops.items()):
    unique = set(flist)
    if len(unique) > 1:
        print(f"  {m}: {unique}")
    else:
        print(f"  {m}: {unique.pop():.4f} (consistent across groups)")
